// Valider et preparer les parametres de batch
const input = $input.first().json;
const body = input.body || input;

// Configuration par defaut
const defaultConfig = {
  target_language: 'fr',
  translator: { provider: 'anthropic', model: 'claude-3-5-sonnet-20241022' },
  reviewer: { provider: 'openai', model: 'gpt-4o' },
  apply_grammalecte: true,
  include_commentaries: true,
  max_commentaries_per_text: 10
};

const config = { ...defaultConfig, ...body.config };

// Validation
const errors = [];
if (!body.book && !body.source_text_ids) {
  errors.push('Specify either "book" (e.g., "Sukkah") or "source_text_ids" array');
}

if (body.book && !['Sukkah', 'Berakhot', 'Pesachim', 'Shabbat', 'Eruvin', 'Bekhorot'].includes(body.book)) {
  errors.push('Invalid book. Available: Sukkah, Berakhot, Pesachim, Shabbat, Eruvin, Bekhorot');
}

const result = {
  valid: errors.length === 0,
  errors: errors,
  params: {
    book: body.book || null,
    chapter_start: body.chapter_start || '2a',
    chapter_end: body.chapter_end || null,
    source_text_ids: body.source_text_ids || [],
    config: config,
    batch_id: `batch_${Date.now()}`
  }
};

return [{ json: result }];

// Preparer les items pour le traitement batch
const apiResponse = $input.first().json;
const params = $('Validate Batch Parameters').first().json.params;

// Extraire les textes de la reponse API
let texts = [];
if (apiResponse.items) {
  texts = apiResponse.items;
} else if (apiResponse.source_texts) {
  texts = apiResponse.source_texts;
} else if (Array.isArray(apiResponse)) {
  texts = apiResponse;
}

// Filtrer par plage de chapitres si specifie
if (params.chapter_start || params.chapter_end) {
  const parseRef = (ref) => {
    const match = ref.match(/(\d+)([ab])/i);
    if (!match) return { num: 0, side: 'a' };
    return { num: parseInt(match[1]), side: match[2].toLowerCase() };
  };

  const start = params.chapter_start ? parseRef(params.chapter_start) : { num: 0, side: 'a' };
  const end = params.chapter_end ? parseRef(params.chapter_end) : { num: 999, side: 'b' };

  texts = texts.filter(t => {
    const ref = parseRef(t.reference || t.ref || '');
    const startVal = start.num * 2 + (start.side === 'b' ? 1 : 0);
    const endVal = end.num * 2 + (end.side === 'b' ? 1 : 0);
    const refVal = ref.num * 2 + (ref.side === 'b' ? 1 : 0);
    return refVal >= startVal && refVal <= endVal;
  });
}

// Limiter le nombre de textes si trop grand
const maxTexts = 50;
if (texts.length > maxTexts) {
  texts = texts.slice(0, maxTexts);
}

// Creer les items de batch (API v2: support segment_id)
const batchItems = texts.map((text, index) => {
  const hasSegmentId = !!text.segment_id;
  return {
    json: {
      id: text.segment_id || text.uuid || text.id,
      id_type: hasSegmentId ? 'segment' : 'source_text',
      segment_id: text.segment_id || null,
      source_text_id: hasSegmentId ? null : (text.uuid || text.id),
      reference: text.reference || text.ref,
      book: params.book,
      index: index + 1,
      total: texts.length,
      batch_id: params.batch_id,
      config: params.config
    }
  };
});

// Si aucun texte, retourner un item vide avec erreur
if (batchItems.length === 0) {
  return [{ json: { error: 'Aucun texte trouve pour les criteres specifies', texts_count: 0 } }];
}

return batchItems;

