// Gerer le resultat de traduction
const input = $input.first().json;
const batchItem = $('Process Texts').item.json;

const result = {
  source_text_id: batchItem.source_text_id,
  reference: batchItem.reference,
  index: batchItem.index,
  total: batchItem.total,
  success: !input.error && !input.detail,
  error: input.error || input.detail || null,
  translation_id: input.translation_id || null,
  comments_translated: input.comments_count || 0,
  tokens_used: input.tokens_used || 0
};

return [{ json: result }];

// Calculer les statistiques finales
const results = $input.first().json.data || [];

const stats = {
  batch_id: results[0]?.batch_id || 'unknown',
  total_texts: results.length,
  successful: results.filter(r => r.success).length,
  failed: results.filter(r => !r.success).length,
  total_comments_translated: results.reduce((sum, r) => sum + (r.comments_translated || 0), 0),
  total_tokens: results.reduce((sum, r) => sum + (r.tokens_used || 0), 0),
  errors: results.filter(r => r.error).map(r => ({ ref: r.reference, error: r.error }))
};

stats.success_rate = stats.total_texts > 0 
  ? Math.round(stats.successful / stats.total_texts * 100) 
  : 0;

return [{ json: { stats, results } }];

